import base64
import csv
import gzip
import io

INITIAL_CATALOG_SOURCE_KEY = "store-prices-2026-10-07-v1"
INITIAL_CATALOG_SOURCE_NAME = "Store Prices 10.7.26.xlsx"
_INITIAL_CSV_GZIP_B64 = ""


def initial_catalog_rows():
    raw = gzip.decompress(base64.b64decode(_INITIAL_CSV_GZIP_B64)).decode("utf-8")
    return list(csv.DictReader(io.StringIO(raw)))
